import type { Locale } from "@/lib/i18n/config"

// RGAA statement, generated by the site so it always matches the tests in e2e/a11y-*.
// Provisional values to confirm with the publisher: the date and the publisher name
// (taken from the published legal notice). Update both after a full RGAA audit.
export const DECLARATION_DATE = "2026-11-11"

const PUBLISHER: Record<Locale, string> = {
  fr: "Le Département de l'Orne, pour les cinq départements normands et la Fondation du patrimoine,",
  en: "The Orne Department, on behalf of the five Normandy departments and the Fondation du patrimoine,",
}

const OMBUDSMAN_FORM = "https://formulaire.defenseurdesdroits.fr/"
const OMBUDSMAN_DELEGATES = "https://www.defenseurdesdroits.fr/carte-des-delegues"

type Declaration = { title: string; content: string }

const formatDate = (locale: Locale) =>
  new Intl.DateTimeFormat(locale === "en" ? "en-GB" : "fr-FR", {
    dateStyle: "long",
    timeZone: "Europe/Paris",
  }).format(new Date(`${DECLARATION_DATE}T12:00:00Z`))

const fr = (): Declaration => ({
  title: "Déclaration d'accessibilité",
  content: `${PUBLISHER.fr} s'engage à rendre son site internet accessible conformément à l'article 47 de la loi n° 2005-102 du 11 février 2005.

Cette déclaration d'accessibilité s'applique au site Pierres en Lumières (pierresenlumieres.fr).

## État de conformité

Le site Pierres en Lumières est **non conforme** avec le référentiel général d'amélioration de l'accessibilité (RGAA), version 4.1.2 : aucun audit de conformité complet n'a encore été réalisé. Les tests ci-dessous corrigent les défauts trouvés mais ne mesurent pas un taux de conformité. Il faut pour cela un audit RGAA sur un échantillon de pages.

## Résultats des tests

- **Tests automatisés** (axe-core, critères WCAG 2.1 niveaux A et AA, qui correspondent au RGAA) : aucune anomalie grave ou critique sur les 13 pages publiques, en français et en anglais, sur ordinateur (1440 pixels) et sur mobile (390 pixels), ni sur les écrans principaux de l'administration.
- **Navigation au clavier seul** : filtrer le programme, ouvrir un événement, l'ajouter au carnet de voyage et partager le carnet, rejoindre le formulaire d'inscription, écrire au festival, publier un contenu dans l'administration.
- **Lecture par un lecteur d'écran** (arbre d'accessibilité) : un seul titre principal par page, des titres sans saut de niveau, des zones de navigation nommées, un lien d'évitement en premier, la langue de chaque page déclarée.
- **Présentation** : zones cliquables d'au moins 44 × 44 pixels, contrastes des couleurs vérifiés, animations arrêtées quand le système demande de réduire les animations.

## Contenus non accessibles

### Non-conformités

- Les photos et descriptions des événements importés de Tourinsoft sont saisies par les organisateurs. Leurs photos ont pour alternative textuelle le titre de l'événement, et non une description de l'image.
- La carte interactive est difficile à utiliser avec un lecteur d'écran. Le programme en liste donne les mêmes informations : lieu, commune, dates et horaires.

### Dérogations pour charge disproportionnée

Aucune.

### Contenus non soumis à l'obligation d'accessibilité

- La carte interactive, dont les informations essentielles sont données en texte sur chaque fiche et dans le programme.
- Les contenus de tiers qui ne sont ni financés, ni développés, ni contrôlés par l'éditeur : formulaires d'inscription des départements, pages de collecte de la Fondation du patrimoine, sites présentant l'histoire des lieux.

## Établissement de cette déclaration

Cette déclaration a été établie le ${formatDate("fr")}.

- **Technologies utilisées** : HTML5, CSS, JavaScript, WAI-ARIA.
- **Environnement de test** : navigateur Chromium sous Linux, avec son arbre d'accessibilité.
- **Outils** : axe-core, Playwright.
- **Pages vérifiées** : accueil, programme (liste et carte), fiche d'un événement, inscription, carnet de voyage, actualités, article, le festival, contact, mentions légales, déclaration d'accessibilité, page introuvable, administration.

## Retour d'information et contact

Si vous n'arrivez pas à accéder à un contenu ou à un service, vous pouvez contacter le responsable du site pour être orienté vers une alternative accessible ou obtenir le contenu sous une autre forme, par le [formulaire de contact](/fr/contact).

## Voies de recours

Si vous avez signalé un défaut d'accessibilité qui vous empêche d'accéder à un contenu ou à un service du site, et que vous n'avez pas obtenu de réponse satisfaisante, vous pouvez :

- écrire un message au [Défenseur des droits](${OMBUDSMAN_FORM}) ;
- contacter [le délégué du Défenseur des droits dans votre région](${OMBUDSMAN_DELEGATES}) ;
- envoyer un courrier par la poste (gratuit, ne pas mettre de timbre) : Défenseur des droits, Libre réponse 71120, 75342 Paris CEDEX 07.`,
})

const en = (): Declaration => ({
  title: "Accessibility statement",
  content: `${PUBLISHER.en} is committed to making its website accessible in accordance with article 47 of French law no. 2005-102 of 11 February 2005.

This accessibility statement applies to the Pierres en Lumières website (pierresenlumieres.fr).

## Compliance status

The Pierres en Lumières website is **non-compliant** with the French accessibility framework (RGAA), version 4.1.2: no full compliance audit has been carried out yet. The tests below fix the issues found but do not measure a compliance rate, which requires an RGAA audit on a sample of pages.

## Test results

- **Automated tests** (axe-core, WCAG 2.1 level A and AA criteria, which the RGAA maps onto): no serious or critical issue on the 13 public pages, in French and English, on desktop (1440 pixels) and mobile (390 pixels), nor on the main administration screens.
- **Keyboard only**: filter the programme, open an event, add it to the travel book and share the book, reach the registration form, write to the festival, publish content in the administration.
- **Screen reader reading** (accessibility tree): a single main heading per page, headings without skipped levels, named navigation regions, a skip link first, the language of each page declared.
- **Presentation**: clickable areas of at least 44 × 44 pixels, colour contrast checked, animations stopped when the system asks for reduced motion.

## Non-accessible content

### Non-compliance

- Photos and descriptions of events imported from Tourinsoft are entered by the organisers. Their photos have the event title as text alternative, not a description of the picture.
- The interactive map is hard to use with a screen reader. The programme list gives the same information: place, town, dates and times.

### Disproportionate burden

None.

### Content outside the scope of the legislation

- The interactive map, whose essential information is given as text on each event page and in the programme.
- Third-party content neither funded, developed nor controlled by the publisher: the departments' registration forms, the Fondation du patrimoine fundraising pages, the websites describing the history of the places.

## Preparation of this statement

This statement was prepared on ${formatDate("en")}.

- **Technologies**: HTML5, CSS, JavaScript, WAI-ARIA.
- **Test environment**: Chromium browser on Linux, with its accessibility tree.
- **Tools**: axe-core, Playwright.
- **Pages checked**: home, programme (list and map), event page, registration, travel book, news, article, the festival, contact, legal notice, accessibility statement, page not found, administration.

## Feedback and contact

If you cannot access a piece of content or a service, you can contact the person in charge of the website to be directed to an accessible alternative or to get the content in another form, through the [contact form](/en/contact).

## Enforcement procedure

If you have reported an accessibility issue that prevents you from accessing a piece of content or a service of the website and have not received a satisfactory answer, you can:

- write a message to the [Défenseur des droits](${OMBUDSMAN_FORM}) (French ombudsman);
- contact [the Défenseur des droits delegate in your region](${OMBUDSMAN_DELEGATES});
- send a letter by post (free of charge, no stamp needed): Défenseur des droits, Libre réponse 71120, 75342 Paris CEDEX 07, France.`,
})

export const accessibilityDeclaration = (locale: Locale): Declaration =>
  locale === "en" ? en() : fr()
